  (1, '홈트레이닝 기초', NOW() - INTERVAL 56 DAY, NOW() - INTERVAL 56 DAY, NULL, 'FITNESS', 0, '집에서 할 수 있는 기초 체력 운동을 배웁니다.', 'ACTIVE', 2, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/1/lecture01Thumbnail.png'),
  (2, '집밥 요리 입문', NOW() - INTERVAL 52 DAY, NOW() - INTERVAL 52 DAY, NULL, 'COOK', 0, '초보자도 따라할 수 있는 기본 요리를 배웁니다.', 'ACTIVE', 4, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/2/lecture02Thumbnail.JPG'),
  (3, '프로그래밍 기초', NOW() - INTERVAL 48 DAY, NOW() - INTERVAL 48 DAY, NULL, 'STUDY', 0, '변수, 조건문, 반복문 등 프로그래밍의 기초를 배웁니다.', 'ACTIVE', 6, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/3/lecture03Thumbnail.WEBP'),
  (4, '요가 기초', NOW() - INTERVAL 44 DAY, NOW() - INTERVAL 44 DAY, NULL, 'FITNESS', 0, '몸의 유연성과 균형을 키우는 기초 요가를 배웁니다.', 'ACTIVE', 3, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/4/lecture04Thumbnail.jpeg'),
  (5, '스킨케어 루틴', NOW() - INTERVAL 40 DAY, NOW() - INTERVAL 40 DAY, NULL, 'BEAUTY', 0, '피부 타입별 기초 스킨케어 방법을 배웁니다.', 'ACTIVE', 8, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/5/lecture05Thumbnail.jpeg'),
  (6, '메이크업 기초', NOW() - INTERVAL 36 DAY, NOW() - INTERVAL 36 DAY, NULL, 'BEAUTY', 0, '데일리 메이크업부터 포인트 메이크업까지 기초를 배웁니다.', 'ACTIVE', 8, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/6/lecture06Thumbnail.jpeg'),
  (7, '수채화 입문', NOW() - INTERVAL 32 DAY, NOW() - INTERVAL 32 DAY, NULL, 'ART', 0, '색감과 번짐 기법을 활용한 수채화 기초를 배웁니다.', 'ACTIVE', 9, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/7/lecture07Thumbnail.jpeg'),
  (8, '드로잉 기초', NOW() - INTERVAL 28 DAY, NOW() - INTERVAL 28 DAY, NULL, 'ART', 0, '선 긋기부터 인체 드로잉까지 기초 드로잉을 배웁니다.', 'ACTIVE', 9, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/8/lecture08Thumbnail.jpeg'),
  (9, '베이킹 기초', NOW() - INTERVAL 24 DAY, NOW() - INTERVAL 24 DAY, NULL, 'COOK', 0, '쿠키, 케이크 등 홈베이킹의 기초를 배웁니다.', 'ACTIVE', 5, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/9/lecture09Thumbnail.jpeg'),
  (10, '영어 회화 기초', NOW() - INTERVAL 20 DAY, NOW() - INTERVAL 20 DAY, NULL, 'STUDY', 0, '일상에서 바로 쓸 수 있는 영어 회화 표현을 배웁니다.', 'ACTIVE', 7, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/10/lecture10Thumbnail.jpeg'),
  (11, '실전 홈트레이닝 심화', NOW() - INTERVAL 22 DAY, NOW() - INTERVAL 22 DAY, NULL, 'FITNESS', 0, '집에서 할 수 있는 기초 체력 운동을 배웁니다.', 'ACTIVE', 2, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/11/lecture11Thumbnail.jpg'),
  (12, '초스피드 자취 요리', NOW() - INTERVAL 54 DAY, NOW() - INTERVAL 54 DAY, NULL, 'COOK', 0, '초보자도 따라할 수 있는 기본 요리를 배웁니다.', 'ACTIVE', 4, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/12/lecture12Thumbnail.jpg'),
