  (50, '영어 회화 기초 심화반 40', NOW() - INTERVAL 19 DAY, NOW() - INTERVAL 19 DAY, NULL, 'STUDY', 0, '일상에서 바로 쓸 수 있는 영어 회화 표현을 배웁니다.', 'ACTIVE', 7, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/50/lecture50Thumbnail.jpg'),
  (51, '부상 부담을 줄이며 완주하는 5km 러닝 입문', NOW() - INTERVAL 65 DAY, NOW() - INTERVAL 65 DAY, NULL, 'FITNESS', 0, '러닝을 처음 시작하는 학습자가 워밍업, 착지 자세, 호흡과 페이스 조절법을 익히고 단계적으로 거리를 늘려 5km 완주에 도전하는 강의입니다.', 'ACTIVE', 2, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/1/lecture01Thumbnail.png'),
  (52, '직장인을 위한 거북목과 굽은 어깨 교정 운동', NOW() - INTERVAL 64 DAY, NOW() - INTERVAL 64 DAY, NULL, 'FITNESS', 0, '장시간 앉아서 생활하는 직장인이 목과 가슴 주변의 긴장을 풀고 등 근육을 활성화하여 올바른 상체 정렬과 업무 자세를 만드는 강의입니다.', 'ACTIVE', 3, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/34/lecture34Thumbnail.webp'),
  (53, '덤벨 하나로 완성하는 초보자 전신 근력 운동', NOW() - INTERVAL 63 DAY, NOW() - INTERVAL 63 DAY, NULL, 'FITNESS', 0, '덤벨을 처음 사용하는 학습자가 스쿼트, 로우와 프레스 같은 기본 동작을 안전하게 익히고 전신 근력을 균형 있게 발달시키는 강의입니다.', 'ACTIVE', 2, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/31/lecture31Thumbnail.jpg'),
  (54, '케틀벨 스윙부터 전신 복합 운동까지', NOW() - INTERVAL 62 DAY, NOW() - INTERVAL 62 DAY, NULL, 'FITNESS', 0, '케틀벨의 올바른 그립과 힙 힌지 동작을 익힌 뒤 스윙, 스쿼트, 클린과 프레스를 연결하여 근력과 심폐 지구력을 함께 기르는 강의입니다.', 'ACTIVE', 3, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/21/lecture21Thumbnail.jpg'),
  (55, '허리를 보호하는 맨몸 코어 안정화 운동', NOW() - INTERVAL 61 DAY, NOW() - INTERVAL 61 DAY, NULL, 'FITNESS', 0, '복부에 힘을 주는 방법과 중립 척추 자세를 이해하고 데드버그, 버드독과 플랭크를 통해 일상과 운동에 필요한 코어 안정성을 기르는 강의입니다.', 'ACTIVE', 2, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/24/lecture24Thumbnail.jpg'),
  (56, 'Python과 Pandas로 시작하는 실전 데이터 분석', NOW() - INTERVAL 60 DAY, NOW() - INTERVAL 60 DAY, NULL, 'STUDY', 0, 'Python과 Pandas를 활용하여 CSV 데이터를 불러오고 결측값을 정리한 뒤 집계와 시각화를 수행하는 데이터 분석 입문 강의입니다.', 'ACTIVE', 6, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/3/lecture03Thumbnail.WEBP'),
  (57, '업무 데이터를 다루는 실전 SQL 쿼리 작성법', NOW() - INTERVAL 59 DAY, NOW() - INTERVAL 59 DAY, NULL, 'STUDY', 0, 'SELECT 기본 문법부터 JOIN, 그룹 집계, 서브쿼리와 실행 계획까지 실무 데이터를 조회하고 분석하는 데 필요한 SQL 작성법을 배웁니다.', 'ACTIVE', 7, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/23/lecture23Thumbnail.webp'),
  (58, 'Git과 GitHub로 배우는 팀 협업 워크플로', NOW() - INTERVAL 58 DAY, NOW() - INTERVAL 58 DAY, NULL, 'STUDY', 0, 'Git 저장소 생성부터 브랜치 관리, 충돌 해결, Pull Request와 코드 리뷰까지 팀 개발에 필요한 협업 흐름을 실습하는 강의입니다.', 'ACTIVE', 6, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/33/lecture33Thumbnail.jpg'),
  (59, '상황별 비즈니스 영어 이메일 작성 실습', NOW() - INTERVAL 57 DAY, NOW() - INTERVAL 57 DAY, NULL, 'STUDY', 0, '요청, 일정 조율, 문제 보고와 사과 등 업무에서 자주 접하는 상황을 중심으로 명확하고 정중한 영어 이메일을 작성하는 방법을 배웁니다.', 'ACTIVE', 7, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/30/lecture30Thumbnail.jpg'),
  (60, '업무 생산성을 높이는 생성형 AI 프롬프트 작성법', NOW() - INTERVAL 56 DAY, NOW() - INTERVAL 56 DAY, NULL, 'STUDY', 0, '생성형 AI에 목표와 맥락, 제약 조건과 출력 형식을 명확하게 전달하여 문서 작성, 요약과 아이디어 정리 업무의 품질을 높이는 강의입니다.', 'ACTIVE', 6, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/13/lecture13Thumbnail.jpg'),
  (61, '냉장고 재료로 완성하는 일주일 밑반찬', NOW() - INTERVAL 55 DAY, NOW() - INTERVAL 55 DAY, NULL, 'COOK', 0, '자주 사용하는 식재료를 효율적으로 손질하고 볶음, 조림과 무침 반찬을 만들어 일주일 식사를 준비하는 실용적인 집밥 강의입니다.', 'ACTIVE', 4, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/2/lecture02Thumbnail.JPG'),
  (62, '균형 잡힌 한 끼를 위한 고단백 도시락 만들기', NOW() - INTERVAL 54 DAY, NOW() - INTERVAL 54 DAY, NULL, 'COOK', 0, '닭고기, 달걀, 두부와 잡곡을 활용하여 단백질과 채소를 균형 있게 담은 일주일 도시락을 준비하고 보관하는 방법을 배웁니다.', 'ACTIVE', 5, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/29/lecture29Thumbnail.jpg'),
  (63, '육수부터 양념까지 배우는 한식 국과 찌개', NOW() - INTERVAL 53 DAY, NOW() - INTERVAL 53 DAY, NULL, 'COOK', 0, '기본 육수를 내는 방법과 재료별 양념 비율을 익혀 미역국, 된장찌개와 김치찌개 등 일상적인 한식 국물 요리를 완성하는 강의입니다.', 'ACTIVE', 4, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/22/lecture22Thumbnail.jpg'),
  (64, '설거지를 줄이는 팬 하나 원팬 요리', NOW() - INTERVAL 52 DAY, NOW() - INTERVAL 52 DAY, NULL, 'COOK', 0, '팬 하나에서 재료를 순서대로 익히는 방법과 불 조절을 배워 볶음밥, 파스타와 닭고기 요리를 간편하게 완성하는 강의입니다.', 'ACTIVE', 5, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/32/lecture32Thumbnail.jpg'),
  (65, '에어프라이어로 만드는 간편한 집밥과 간식', NOW() - INTERVAL 51 DAY, NOW() - INTERVAL 51 DAY, NULL, 'COOK', 0, '에어프라이어의 온도와 시간을 재료에 맞게 조절하여 채소, 닭고기, 생선과 간식을 겉은 바삭하고 속은 촉촉하게 조리하는 강의입니다.', 'ACTIVE', 4, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/12/lecture12Thumbnail.jpg'),
  (66, '민감성 피부를 위한 저자극 장벽 관리 루틴', NOW() - INTERVAL 50 DAY, NOW() - INTERVAL 50 DAY, NULL, 'BEAUTY', 0, '민감해진 피부의 상태를 점검하고 순한 세안, 보습 성분과 자외선 차단을 중심으로 자극을 줄인 일상 관리 루틴을 만드는 강의입니다.', 'ACTIVE', 8, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/5/lecture05Thumbnail.jpeg'),
  (67, '트러블 피부를 위한 위생적인 데일리 케어', NOW() - INTERVAL 49 DAY, NOW() - INTERVAL 49 DAY, NULL, 'BEAUTY', 0, '피부와 화장 도구의 위생을 관리하고 과도한 자극을 피하는 세안과 보습 방법을 익혀 트러블 피부의 데일리 루틴을 정리하는 강의입니다.', 'ACTIVE', 8, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/15/lecture15Thumbnail.jpg'),
  (68, '두피 타입별 샴푸와 손상 모발 관리법', NOW() - INTERVAL 48 DAY, NOW() - INTERVAL 48 DAY, NULL, 'BEAUTY', 0, '두피와 모발 상태를 구분하고 올바른 샴푸, 건조와 트리트먼트 방법을 익혀 두피 청결과 모발 컨디션을 함께 관리하는 강의입니다.', 'ACTIVE', 8, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/25/lecture25Thumbnail.jpg'),
  (69, '기초 손질부터 컬러링까지 셀프 네일 클래스', NOW() - INTERVAL 47 DAY, NOW() - INTERVAL 47 DAY, NULL, 'BEAUTY', 0, '손톱 모양 정리와 큐티클 관리부터 베이스, 컬러, 포인트 디자인과 안전한 제거까지 셀프 네일의 전체 과정을 배우는 강의입니다.', 'ACTIVE', 8, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/35/lecture35Thumbnail.jpg'),
  (70, '아침 시간을 줄이는 지속력 좋은 출근 메이크업', NOW() - INTERVAL 46 DAY, NOW() - INTERVAL 46 DAY, NULL, 'BEAUTY', 0, '얇고 오래 유지되는 피부 표현과 자연스러운 눈썹, 아이 메이크업과 립 연출을 통해 짧은 시간에 출근 메이크업을 완성하는 강의입니다.', 'ACTIVE', 8, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/6/lecture06Thumbnail.jpeg'),
  (71, '색의 깊이를 표현하는 아크릴 풍경화 입문', NOW() - INTERVAL 45 DAY, NOW() - INTERVAL 45 DAY, NULL, 'ART', 0, '아크릴 물감의 농도와 붓 사용법을 익히고 하늘, 나무와 건물을 여러 층으로 채색하여 깊이감 있는 풍경화를 완성하는 강의입니다.', 'ACTIVE', 9, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/17/lecture17Thumbnail.jpg'),
  (72, '색연필로 그리는 섬세한 보태니컬 일러스트', NOW() - INTERVAL 44 DAY, NOW() - INTERVAL 44 DAY, NULL, 'ART', 0, '꽃과 잎의 기본 형태를 관찰하고 색연필의 겹칠과 명암 표현을 활용하여 섬세한 식물 일러스트를 완성하는 강의입니다.', 'ACTIVE', 9, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/7/lecture07Thumbnail.jpeg'),
  (73, '여행의 순간을 기록하는 어반 스케치', NOW() - INTERVAL 43 DAY, NOW() - INTERVAL 43 DAY, NULL, 'ART', 0, '펜과 수채 도구를 이용해 거리의 건물, 사람과 소품을 빠르게 관찰하고 원근감과 현장 분위기가 담긴 여행 스케치를 그리는 강의입니다.', 'ACTIVE', 9, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/36/lecture36Thumbnail.jpg'),
  (74, '레이어부터 채색까지 디지털 캐릭터 디자인', NOW() - INTERVAL 42 DAY, NOW() - INTERVAL 42 DAY, NULL, 'ART', 0, '디지털 드로잉 도구의 레이어와 브러시 기능을 익히고 캐릭터의 실루엣, 표정, 의상과 색상을 설계하여 완성도 높은 캐릭터를 제작합니다.', 'ACTIVE', 9, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/18/lecture18Thumbnail.png'),
  (75, '스마트폰으로 배우는 사진 구도와 감성 보정', NOW() - INTERVAL 41 DAY, NOW() - INTERVAL 41 DAY, NULL, 'ART', 0, '스마트폰 카메라의 노출과 초점을 조절하고 다양한 구도와 색상 보정을 적용하여 일상 사진을 하나의 일관된 작품으로 만드는 강의입니다.', 'ACTIVE', 9, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/28/lecture28Thumbnail.jpg')
