  (262, NOW() - INTERVAL 64 DAY, NOW() - INTERVAL 64 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/1/chapters/3/chapter03Thumbnail.jpg', 805, 52, 3, NULL, '짧아진 가슴 근육을 이완해 앞으로 말린 어깨 공간 확보하기', NULL, 'lectures/1/chapters/3/chapter03.mp4'),
  (263, NOW() - INTERVAL 64 DAY, NOW() - INTERVAL 64 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/1/chapters/4/chapter04Thumbnail.jpg', 217, 52, 4, NULL, '날개뼈를 안정적으로 모으는 동작으로 등 근육 강화하기', NULL, 'lectures/1/chapters/4/chapter04.mp4'),
  (264, NOW() - INTERVAL 64 DAY, NOW() - INTERVAL 64 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/4/chapters/1/chapter12Thumbnail.jpg', 354, 52, 5, NULL, '업무 중 매시간 실천하는 5분 목과 어깨 교정 루틴 완성하기', NULL, 'lectures/4/chapters/1/chapter01.mp4'),
  (265, NOW() - INTERVAL 63 DAY, NOW() - INTERVAL 63 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/1/chapters/1/chapter01Thumbnail.jpg', 354, 53, 1, NULL, '운동 수준에 맞는 덤벨 무게를 고르고 안전한 그립 익히기', NULL, 'lectures/1/chapters/1/chapter01.mp4'),
  (266, NOW() - INTERVAL 63 DAY, NOW() - INTERVAL 63 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/1/chapters/2/chapter02Thumbnail.jpg', 200, 53, 2, NULL, '덤벨 고블릿 스쿼트로 엉덩이와 허벅지 근력 강화하기', NULL, 'lectures/1/chapters/2/chapter02.mp4'),
  (267, NOW() - INTERVAL 63 DAY, NOW() - INTERVAL 63 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/1/chapters/3/chapter03Thumbnail.jpg', 805, 53, 3, NULL, '힙 힌지 자세를 유지하는 덤벨 루마니안 데드리프트 배우기', NULL, 'lectures/1/chapters/3/chapter03.mp4'),
  (268, NOW() - INTERVAL 63 DAY, NOW() - INTERVAL 63 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/1/chapters/4/chapter04Thumbnail.jpg', 217, 53, 4, NULL, '한 팔 덤벨 로우로 날개뼈를 움직이며 등 근육 강화하기', NULL, 'lectures/1/chapters/4/chapter04.mp4'),
  (269, NOW() - INTERVAL 63 DAY, NOW() - INTERVAL 63 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/4/chapters/1/chapter12Thumbnail.jpg', 354, 53, 5, NULL, '스쿼트와 로우 및 프레스를 연결한 전신 서킷 수행하기', NULL, 'lectures/4/chapters/1/chapter01.mp4'),
  (270, NOW() - INTERVAL 62 DAY, NOW() - INTERVAL 62 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/1/chapters/1/chapter01Thumbnail.jpg', 354, 54, 1, NULL, '케틀벨 구조와 기본 그립을 이해하고 안전하게 내려놓기', NULL, 'lectures/1/chapters/1/chapter01.mp4'),
  (271, NOW() - INTERVAL 62 DAY, NOW() - INTERVAL 62 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/1/chapters/2/chapter02Thumbnail.jpg', 200, 54, 2, NULL, '힙 힌지 동작으로 허리 대신 엉덩이에 힘 전달하기', NULL, 'lectures/1/chapters/2/chapter02.mp4'),
  (272, NOW() - INTERVAL 62 DAY, NOW() - INTERVAL 62 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/1/chapters/3/chapter03Thumbnail.jpg', 805, 54, 3, NULL, '팔이 아닌 엉덩이 반동을 사용하는 케틀벨 스윙 완성하기', NULL, 'lectures/1/chapters/3/chapter03.mp4'),
  (273, NOW() - INTERVAL 62 DAY, NOW() - INTERVAL 62 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/1/chapters/4/chapter04Thumbnail.jpg', 217, 54, 4, NULL, '케틀벨 고블릿 스쿼트로 몸통 안정성과 하체 근력 높이기', NULL, 'lectures/1/chapters/4/chapter04.mp4'),
  (274, NOW() - INTERVAL 62 DAY, NOW() - INTERVAL 62 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/4/chapters/1/chapter12Thumbnail.jpg', 354, 54, 5, NULL, '스윙과 스쿼트를 조합한 15분 케틀벨 서킷 수행하기', NULL, 'lectures/4/chapters/1/chapter01.mp4'),
  (275, NOW() - INTERVAL 61 DAY, NOW() - INTERVAL 61 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/1/chapters/1/chapter01Thumbnail.jpg', 354, 55, 1, NULL, '누운 자세에서 중립 척추와 골반 위치를 스스로 확인하기', NULL, 'lectures/1/chapters/1/chapter01.mp4'),
  (276, NOW() - INTERVAL 61 DAY, NOW() - INTERVAL 61 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/1/chapters/2/chapter02Thumbnail.jpg', 200, 55, 2, NULL, '복식 호흡과 복부 브레이싱을 연결해 몸통 단단하게 만들기', NULL, 'lectures/1/chapters/2/chapter02.mp4'),
  (277, NOW() - INTERVAL 61 DAY, NOW() - INTERVAL 61 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/1/chapters/3/chapter03Thumbnail.jpg', 805, 55, 3, NULL, '데드버그 동작으로 허리를 고정한 채 팔다리 움직이기', NULL, 'lectures/1/chapters/3/chapter03.mp4'),
  (278, NOW() - INTERVAL 61 DAY, NOW() - INTERVAL 61 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/1/chapters/4/chapter04Thumbnail.jpg', 217, 55, 4, NULL, '버드독 동작으로 몸통 회전을 억제하고 좌우 균형 잡기', NULL, 'lectures/1/chapters/4/chapter04.mp4'),
  (279, NOW() - INTERVAL 61 DAY, NOW() - INTERVAL 61 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/4/chapters/1/chapter12Thumbnail.jpg', 354, 55, 5, NULL, '데드버그부터 플랭크까지 연결한 15분 코어 루틴 완성하기', NULL, 'lectures/4/chapters/1/chapter01.mp4'),
  (280, NOW() - INTERVAL 60 DAY, NOW() - INTERVAL 60 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/3/chapters/1/chapter10Thumbnail.jpg', 354, 56, 1, NULL, 'Python 실행 환경과 Jupyter Notebook의 기본 사용법 익히기', NULL, 'lectures/3/chapters/1/chapter01.mp4'),
  (281, NOW() - INTERVAL 60 DAY, NOW() - INTERVAL 60 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/3/chapters/2/chapter11Thumbnail.jpg', 200, 56, 2, NULL, 'CSV 데이터를 불러오고 자료형과 결측값을 정리하기', NULL, 'lectures/3/chapters/2/chapter02.mp4'),
  (282, NOW() - INTERVAL 60 DAY, NOW() - INTERVAL 60 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/10/chapters/1/chapter44Thumbnail.jpg', 354, 56, 3, NULL, '조건 필터링과 정렬 및 그룹 집계로 데이터 요약하기', NULL, 'lectures/10/chapters/1/chapter01.mp4'),
  (283, NOW() - INTERVAL 60 DAY, NOW() - INTERVAL 60 DAY, NULL, 'https://momocity-media.s3.ap-northeast-2.amazonaws.com/lectures/10/chapters/2/chapter45Thumbnail.jpg', 200, 56, 4, NULL, '막대그래프와 선그래프로 데이터의 변화와 차이 표현하기', NULL, 'lectures/10/chapters/2/chapter02.mp4'),
